{
  "title": "迷失的图书馆",
  "scene": "你被困在一个古老的图书馆里，书架密集，尘封的书页上似乎有着古老的知识。图书馆中央有一张桌子，上面摆放着一本看似普通却散发着微光的书。周围弥漫着一股神秘的气息。",
  "goal": "找到图书馆的秘密出口，并安全离开。",
  "choices": [
    {
      "id": "A",
      "text": "拿起书本并试图阅读，希望能找到线索。",
      "outcome": "书页轻轻翻动，发出轻微的响声，但只是记录了一些模糊的符号。",
      "result": "partial",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "在书架间仔细寻找，希望能找到一扇隐藏的门。",
      "outcome": "发现了一本看似与周围书本不同的古旧书籍，轻轻一推，书架之间出现了一道暗门。",
      "result": "success",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "听从直觉，朝着图书馆的深处走去，看看是否有其他线索。",
      "outcome": "走进图书馆深处后，你意外碰到了一个陷阱，不小心触发了机关，几本书从天而降，差点砸到你。",
      "result": "fail",
      "next": "bad_end"
    }
  ]
